Definition rv_atA (m : amem) (WK : Z) (rv : list Z) (P : Z -> Prop) : Prop :=
  exists rvw : list word, length rvw = 156%nat /\ u32arr asegs m WK rvw /\
    forall i, P i -> 0 <= i < 156 -> nth (Z.to_nat i) rvw (Z_to_bv 64 0) = Z_to_bv 64 (Znth i rv).

Lemma rv_atA_transport : forall W m m' WK rv P, rv_atA m WK rv P -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W WK 624 -> rv_atA m' WK rv P.
Proof.
